package dlpool

import "time"

// Options tunes a Manager.
//
//   - BatchSize: how many files download concurrently; the next batch
//     starts only after the previous one has fully drained.
//   - Attempts: total tries per file before it is reported failed.
//   - BaseDelay / MaxDelay: retry pacing. The pause before a file's first
//     retry is BaseDelay, and it doubles for each further retry of that
//     file, capped at MaxDelay.
//   - Sleep: how to pause between attempts; injectable for tests and
//     defaults to time.Sleep.
type Options struct {
	BatchSize int
	Attempts  int
	BaseDelay time.Duration
	MaxDelay  time.Duration
	Sleep     func(time.Duration)
}

func withDefaults(opts Options) Options {
	if opts.BatchSize <= 0 {
		opts.BatchSize = 4
	}
	if opts.Attempts <= 0 {
		opts.Attempts = 3
	}
	if opts.BaseDelay <= 0 {
		opts.BaseDelay = 100 * time.Millisecond
	}
	if opts.MaxDelay <= 0 {
		opts.MaxDelay = 2 * time.Second
	}
	if opts.Sleep == nil {
		opts.Sleep = time.Sleep
	}
	return opts
}

// delayFor returns the pause to take before the retry that follows the
// given (1-based) attempt. The pause starts at BaseDelay and doubles for
// each further retry, capped at MaxDelay. Because pacing is a pure
// function of the attempt number, every file backs off from BaseDelay
// independently instead of climbing across the whole run.
func (m *Manager) delayFor(attempt int) time.Duration {
	d := m.opts.BaseDelay
	for i := 1; i < attempt && d < m.opts.MaxDelay; i++ {
		d *= 2
	}
	if d > m.opts.MaxDelay {
		return m.opts.MaxDelay
	}
	return d
}

