use rs_varint::{
    decode_all_i64, decode_all_u64, encode_i64, encode_u64, zigzag_decode, zigzag_encode,
    DecodeError, Decoder,
};

fn enc_u(values: &[u64]) -> Vec<u8> {
    let mut out = Vec::new();
    for &v in values {
        encode_u64(v, &mut out);
    }
    out
}

fn enc_i(values: &[i64]) -> Vec<u8> {
    let mut out = Vec::new();
    for &v in values {
        encode_i64(v, &mut out);
    }
    out
