import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildAccessors, renderReport } from './report.ts';

const columns = [
  { header: 'Name', key: 'name' },
  { header: 'Email', key: 'email' },
  { header: 'Seats', key: 'seats', format: (v: unknown) => `x${v}` },
