	return toks
}

// Count tallies token frequencies across all shards in parallel and returns
// the combined counts.
//
// Go maps are not safe for concurrent use, so each shard is tallied into its
// own local map on a dedicated goroutine (keeping the tokenize/tally work
// fully parallel for throughput). The per-shard results are then merged into
// the returned map serially after all goroutines finish. Writing distinct
// perShard[i] slots needs no synchronization, and wg.Wait establishes the
// happens-before edge that makes the subsequent merge safe.
func Count(shards [][]string) map[string]int {
	perShard := make([]map[string]int, len(shards))
	var wg sync.WaitGroup
	for i, shard := range shards {
		wg.Add(1)
		go func(i int, shard []string) {
			defer wg.Done()
			local := make(map[string]int)
			for _, line := range shard {
				for _, tok := range Tokenize(line) {
					local[tok]++
				}
			}
			perShard[i] = local
		}(i, shard)
	}
	wg.Wait()

	counts := make(map[string]int)
	for _, local := range perShard {
		for tok, n := range local {
			counts[tok] += n
		}
	}
	return counts
}

// Top returns the count for a single token (0 if unseen).
func Top(counts map[string]int, token string) int {
	return counts[strings.ToLower(token)]
}

